T["Nichts geplant - wie waer's mit einem Termin?"] = "Ничего не запланировано - может, устроим событие?"
T["Nichts gesucht. Trag oben ein, was du brauchst -\nalle mit Oasis sehen es im Tooltip und bekommen beim Looten einen Hinweis."] = "Ничего не разыскивается. Впиши сверху, что тебе нужно –\nвсе с Oasis увидят это во всплывающей подсказке и получат уведомление при получении предмета."
