T["Niedrigster Beruf +1 - oder 2-4 Elementaressenzen, wenn alle maximal."] = "Самая низкая профессия +1 – или 2–4 эссенции стихий, если все максимальны."
T["Niemand in der Gilde hat es gerade - ab auf die Liste!"] = "Сейчас в гильдии этого ни у кого нет – добавь в список!"
T["Nimm Quests an - Oasis zeigt dir, wer aus der Gilde dieselben hat."] = "Бери квесты – Oasis покажет, у кого из гильдии такие же."
T["Noch Standard-Einstellungen."] = "Пока стандартные настройки."
T["Noch kein Protokoll."] = "Журнала пока нет."
T["Noch kein Protokoll. Es wird gelesen, wenn jemand mit Oasis die Bank oeffnet."] = "Журнала пока нет. Он читается, когда кто-то с Oasis открывает банк."
T["Noch kein Scan"] = "Ещё нет скана"
T["Noch kein Scan in der Gilde."] = "В гильдии ещё никто не сканировал."
T["Noch keine Abzeichen."] = "Значков пока нет."
T["Noch keine Antworten."] = "Ответов пока нет."
T["Noch keine Beute erfasst (ab Qualitaet 'Selten', einstellbar)."] = "Добыча пока не зафиксирована (от качества «редкий», настраивается)."
T["Noch keine Bio."] = "Био пока нет."
T["Noch keine Daten aus der Gilde."] = "Данных гильдии пока нет."
T["Noch keine Durchsagen."] = "Объявлений пока нет."
T["Noch keine Gilden-News."] = "Новостей гильдии пока нет."
T["Noch keine Items verlinkt."] = "Предметы ещё не ссылались."
T["Noch keine Mitspieler von ausserhalb der Gilde.\nWer mit dir in einer Gruppe war, landet automatisch hier."] = "Игроков вне гильдии пока нет.\nКто был с тобой в группе, попадёт сюда автоматически."
T["Noch keine Nachrichten. Alles, was ab jetzt im Gildenchat geschrieben wird, landet hier."] = "Сообщений пока нет. Всё, что напишут в чат гильдии, появится здесь."
T["Noch keine Positionen."] = "Позиций пока нет."
T["Noch keine Posts. Klick auf 'Neuer Schnappschuss' oder auf die Kamera in der Oasis-Leiste!"] = "Постов пока нет. Нажмите 'Новый снимок' или камеру на панели Oasis!"
T["Noch keine Punkte.\nSobald ein Offizier einen Raid startet, gibt es Einsatz-Punkte fuer alle, die dabei sind."] = "Очков пока нет.\nКак только офицер начнёт рейд, все участники получат очки за участие."
T["Noch keine Rezepte bekannt.\nOeffne deine Berufsfenster einmal - Oasis teilt sie dann automatisch mit der Gilde."] = "Рецепты пока не известны.\nОткрой окно профессии один раз – Oasis автоматически поделится ими с гильдией."
T["Noch keine Rezepte geteilt.\n\nSobald jemand mit Oasis sein Berufsfenster oeffnet, erscheinen die Rezepte hier. Wer welchen Beruf hat, siehst du schon jetzt:"] = "Рецептов пока нет.\n\nКак только кто-то с Oasis откроет окно профессии, рецепты появятся здесь. Кто какой профессией владеет, видно уже сейчас:"
T["Noch keine Spiele."] = "Игр пока нет."
T["Noch keine Umfragen."] = "Опросов пока нет."
T["Noch keine bekannt - sobald jemand mit Oasis eine Quest fuer diesen Dungeon hat, steht sie hier."] = "Пока ничего не известно – как только у кого-то с Oasis появится квест для этого подземелья, он появится здесь."
T["Noch leer. Setz dich an ein Lagerfeuer und fuege\nden Buff in der Uebersicht ueber '+' zum Katalog hinzu."] = "Пока пусто. Сядь у костра и добавь\nбаф в обзоре через «+» в каталог."
T["Noch leer. Setz dich an ein Lagerfeuer und fuege\nden Buff rechts ueber '+' zum Katalog hinzu."] = "Пока пусто. Сядь у костра и добавь\nбаф справа через «+» в каталог."
T["Noch nichts erledigt."] = "Пока ничего не выполнено."
T["Noch nichts im Feed. Folge Leuten aus der Gilde - ihre Posts landen dann hier."] = "В ленте пока пусто. Подпишитесь на согильдийцев - их посты появятся здесь."
T["Noch nichts passiert."] = "Пока ничего не произошло."
T["Noch nichts passiert. Geht spielen!"] = "Пока ничего не произошло. Идите играть!"
T["Noch niemand - die Gilde ist informiert."] = "Пока никого – гильдия уже оповещена."
T["Noch niemand bekannt. Wer das Rezept hat, teilt es automatisch beim Oeffnen des Berufsfensters."] = "Пока никто не известен. У кого есть рецепт, поделится им автоматически при открытии окна профессии."
T["Noch niemand gestorben. Respekt!"] = "Пока никто не умер. Уважение!"
T["Noch niemand hat dich erwaehnt."] = "Тебя ещё никто не упоминал."
T["Noch niemand teilt seine Handelsbilanz. Links 'Meine Handelsbilanz teilen' einschalten - dann geht's los."] = "Пока никто не делится итогами торговли. Включи слева 'Делиться итогами торговли'."
