T["Alle: Nie vor oder hinter Onyxia stehen (Atem/Schwanz).\nPhase 2 ab 65%: Feuerbaellen ausweichen, Welpen sofort umhauen.\nPhase 3 ab 40%: Furcht - Totem der Erdung und Furchtschutz bereit.\nTank: Onyxia mit dem Ruecken zur Wand, Kopf weg vom Raid.\nTank: Phase 3 sofort Aggro zurueckholen.\nHeiler: Tank hat Vorrang, in Phase 2 verteilt stehen.\nDD: Erst nach 3 Rueckenangriffen des Tanks voll loslegen.\nDD: Phase 2: Welpen vor Onyxia."] = "Все: никогда не стоять перед Ониксией или позади неё (дыхание/хвост).\nФаза 2 с 65%: уклоняться от огненных шаров, щенков убивать сразу.\nФаза 3 с 40%: страх - тотем заземления и защита от страха наготове.\nТанк: Ониксия спиной к стене, голова от рейда.\nТанк: в фазе 3 сразу вернуть агро.\nЛекари: танк в приоритете, в фазе 2 стоять рассредоточенно.\nБойцы: в полную силу только после 3 раскалываний брони от танка.\nБойцы: фаза 2: щенки важнее Ониксии."
T["Alle: Schwarm-Ziel: rauslaufen.\nTank: Infernal-Tank abseits.\nHeiler: Schlaf entfernen, wo moeglich.\nDD: Infernals ignorieren, alles auf den Boss."] = "Все: цель роя - выбегай.\nТанк: танк инферналов в стороне.\nЛекари: снимать сон, где возможно.\nБойцы: игнорировать инферналов, всё на босса."
T["Alle: Tod und Verfall sofort verlassen.\nTank: Mitte halten, bei Frostnova nicht bewegen.\nHeiler: Eisblock-Ziel schnell hochheilen.\nDD: Fernkampf weit verteilt (Eispfeil-Kette)."] = "Все: сразу выходи из «Смерти и разложения».\nТанк: держать центр, не двигаться при кольце льда.\nЛекари: быстро вылечить цель ледяной глыбы.\nБойцы: дальний бой широко рассредоточен (цепь ледяных стрел)."
T["Allein ist das Fenster weg - in der naechsten Gruppe kommt es wieder"] = "В одиночку окно пропадает - в следующей группе вернётся"
