T["Automatisch: Oasis legt alle 10 Minuten und beim Ausloggen einen Schnappschuss in den Gespeicherten Variablen ab (WTF/Account/<Konto>/SavedVariables/Oasis.lua). Das Programm Tools/oasis_export.py liest die Datei, macht JSON daraus und kann es an eure Weboberflaeche schicken. Addons haben keinen Internetzugriff - das ist der sichere Weg."] = "Автоматически: каждые 10 мин. и при выходе Oasis сохраняет снимок в сохранённых переменных (WTF/Account/<учётка>/SavedVariables/Oasis.lua). Программа Tools/oasis_export.py читает файл, делает из него JSON и может отправить на твой сайт. У аддонов нет доступа в интернет - это безопасный путь."
