T["Dein Gildenrang darf keine Raenge vergeben."] = "Твоему званию нельзя назначать звания."
T["Dein Gildenrang darf keine Termine anlegen."] = "Твоему званию нельзя создавать события."
T["Dein Handelsgewinn 7 Tage"] = "Твоя прибыль от торговли за 7 дн."
T["Dein Leben in Azeroth: Reise, Rekorde, Dungeons, Ziele und Jahrbuch"] = "Твоя жизнь в Азероте: путь, рекорды, подземелья, цели и альбом"
T["Dein Main %s ist in <%s>."] = "Твой основной %s в <%s>."
T["Dein Oasis-Rang"] = "Твой ранг Oasis"
T["Dein Online-Sound"] = "Твой звук входа"
T["Dein Online-Sound (hoeren alle mit Oasis)"] = "Твой звук входа (слышат все с Oasis)"
T["Dein Platz"] = "Твоё место"
T["Dein Rang darf den Offizierschat nicht lesen. Das Recht vergibt der Gildenmeister im Blizzard-Gildenfenster."] = "Твоему званию нельзя читать офицерский чат. Право выдаёт глава гильдии в окне гильдии Blizzard."
T["Dein Sound"] = "Твой звук"
T["Dein Spiel liefert das Questlog nicht wie erwartet - die Seite bleibt leer.\nMit /oa probe questitems siehst du, was ankommt."] = "Игра выдаёт журнал заданий не так, как ожидалось - страница пуста.\nЧерез /oa probe questitems видно, что приходит."
T["Dein Stand wurde geteilt."] = "Твой статус отправлен."
T["Dein Tagesziel"] = "Твоя цель на день"
T["Dein Talentbaum ist nicht lesbar."] = "Твоё дерево талантов не читается."
T["Dein Termin"] = "Твоё событие"
T["Dein Ziel zuerst"] = "Сначала твоя цель"
T["Dein aktuelles Ziel bekommt den Totenkopf"] = "Твоя текущая цель получает череп"
T["Dein naechster Raid"] = "Твой следующий рейд"
T["Deine Abzeichen"] = "Твои значки"
T["Deine Aufgabe"] = "Твоя задача"
T["Deine Auswahl bleibt, neue Bereiche kommen dazu."] = "Твой выбор сохранится, добавятся новые разделы."
T["Deine Belohnungen"] = "Твои награды"
T["Deine Bereiche und Einstellungen bleiben genau so, wie sie sind."] = "Твои разделы и настройки останутся точно такими же."
T["Deine Beute"] = "Твоя добыча"
T["Deine Bewertung, Notiz und die Erfahrungen der Gilde beim Drueberfahren"] = "Твоя оценка, заметка и опыт гильдии при наведении"
T["Deine Buffs sind bei allen drauf."] = "Твои баффы есть у всех."
T["Deine Charaktere"] = "Твои персонажи"
T["Deine Einstellungen gelten automatisch fuer alle Charaktere auf diesem Account."] = "Твои настройки автоматически действуют для всех персонажей этой учётной записи."
T["Deine Einstellungen, Spielhilfen und Bereiche bleiben genau so. Neues kommt nur dazu."] = "Твои настройки, игровые помощники и разделы останутся прежними. Новое только добавится."
T["Deine Gruesse"] = "Твои приветствия"
T["Deine Grundfarbe + Akzentfarbe"] = "Твой основной цвет + акцент"
T["Deine Gruppe sucht hier %d Items"] = "Твоя группа ищет здесь предметов: %d"
T["Deine Meldung ist unterwegs zum Entwickler."] = "Твоё сообщение отправлено разработчику."
T["Deine Oasis-Kontakte"] = "Твои контакты Oasis"
T["Deine Regeln"] = "Твои правила"
T["Deine Rekorde"] = "Твои рекорды"
T["Deine Reservierung"] = "Твой резерв"
T["Deine Rolle"] = "Твоя роль"
T["Deine Suche"] = "Твой поиск"
T["Deine Teile - wem helfen sie?"] = "Твои предметы - кому они помогут?"
T["Deine Teile helfen"] = "Твои предметы помогут"
T["Deine Vitrine"] = "Твоя витрина"
T["Deine Waffen"] = "Твоё оружие"
T["Deine Woche"] = "Твоя неделя"
T["Deine handelbaren Teile - wem helfen sie?"] = "Твои передаваемые предметы - кому они помогут?"
T["Demo ansehen"] = "Посмотреть демо"
T["Demo-Daten gibt es nur in der Entwicklerversion."] = "Демо-данные есть только в версии разработчика."
T["Demo: Auftrag wuerde gesendet."] = "Демо: заказ был бы отправлен."
T["Demo: Beispielpreise, nur bei dir sichtbar"] = "Демо: примерные цены, видны только тебе"
T["Demo: Quest wuerde geteilt."] = "Демо: заданием поделились бы."
T["Demo: spielt einen Ready-Check mit der Beispielgruppe durch."] = "Демо: проверка готовности с примерной группой."
T["Demo: wuerde %s Bescheid sagen."] = "Демо: %s получил(а) бы уведомление."
T["Demo: wuerde %s anfluestern."] = "Демо: шепнули бы %s."
T["Demo: wuerde %s einladen."] = "Демо: пригласили бы %s."
T["Den Download findest du in unserem Discord."] = "Скачать можно в нашем Discord."
T["Den Knopf kannst du auch direkt an der Minimap mit der Maus verschieben."] = "Кнопку также можно перетаскивать по мини-карте."
T["Den Raid-Simulator gibt es nur in der Entwicklerversion."] = "Симулятор рейда есть только в версии разработчика."
T["Den Raidplan bearbeiten duerfen Gildenleitung, Schlachtzugsleiter und Raid-Assistenten."] = "Править план рейда могут руководство, лидеры рейда и помощники рейда."
T["Den Talentbaum dieser Klasse kann WoW hier nicht anzeigen. Der Export-Text laesst sich unten kopieren."] = "Дерево талантов этого класса WoW здесь не показывает. Текст экспорта можно скопировать ниже."
T["Den ganzen Verlauf mit %s loeschen? Gemerkte Nachrichten gehen mit."] = "Удалить всю переписку с %s? Сохранённые сообщения тоже удалятся."
T["Der Auftrag geht an alle Handwerker mit diesem Rezept - wer Zeit hat, nimmt ihn an."] = "Заказ уйдёт всем ремесленникам с этим рецептом - у кого есть время, тот возьмёт."
T["Der Auftrag wird fuer alle zurueckgezogen."] = "Заказ отзывается для всех."
T["Der Auftraggeber bekommt Bescheid, dass es fertig ist."] = "Заказчик узнает, что всё готово."
T["Der Auftraggeber bekommt Bescheid."] = "Заказчик получит уведомление."
T["Der Basar ist leer"] = "Базар пуст"
T["Der Brachland-Chat mit seinen Spruechen"] = "Чат Степей с его шуточками"
T["Der Client liefert gerade keine Fertigkeiten - nach dem Einloggen kurz warten."] = "Клиент сейчас не выдаёт навыки - подожди немного после входа."
T["Der Dungeonkompass: welcher Dungeon passt, was droppt dort fuer dich."] = "Компас подземелий: какое подземелье подходит и что там падает для тебя."
T["Der Gegner stand nicht vor dir. Er stand hinter dir. Die ganze Zeit."] = "Враг был не перед тобой. Он был позади. Всё это время."
T["Der Gruppenanfuehrer kann dich zum Assistenten machen."] = "Лидер группы может назначить тебя помощником."
T["Der Kampf war erst gesperrt und wurde nachtraeglich ausgewertet."] = "Бой сначала был заблокирован и обработан позже."
T["Der Knopf laesst sich nicht mehr mit der Maus verschieben"] = "Кнопку больше нельзя перетаскивать мышью"
T["Der Link gilt fuer alle Leitungen."] = "Ссылка действует для всех руководителей."
T["Der Markt nutzt Preise aus dem AH-Addon Midas. Sobald du oder jemand aus der Gilde mit Midas im AH scannt, schaltet sich diese Seite frei."] = "Рынок использует цены из аддона аукциона Midas. Как только ты или кто-то из гильдии просканирует аукцион с Midas, страница откроется."
T["Der Mitschnitt der Spielzeiten ist aus. Schalte ihn ein, dann lernt Oasis mit jedem Abend dazu."] = "Запись игрового времени выключена. Включи её, и Oasis будет учиться каждый вечер."
T["Der Oasis-Rang ist der Gilden-Rang von Oasis - er steigt durch Zusammenspielen, Helfen, Handwerk, Termine und Abzeichen."] = "Ранг Oasis - это ранг в гильдии от Oasis: растёт за совместную игру, помощь, ремесло, события и значки."
T["Der Online-Sound dieser Person ist bei dir aus."] = "Звук входа этого игрока у тебя выключен."
T["Der Rand des Oasis-Fensters leuchtet in deiner Farbe"] = "Рамка окна Oasis светится твоим цветом"
T["Der Ring zeigt, wer ohne offene Punkte ist."] = "Кольцо показывает, у кого нет открытых пунктов."
T["Der Steinfresser"] = "Камнеед"
T["Der Termin liegt in der Vergangenheit."] = "Это время уже прошло."
T["Details"] = "Подробности"
T["Di"] = "Вт"
T["Diagnose und Abgleich"] = "Диагностика и сверка"
T["Diamant"] = "Ромб"
T["Diamant = Verbannen (Hexenmeister)"] = "Ромб = Изгнание (чернокнижник)"
T["Die Bank besucht. Mal kurz nachzaehlen."] = "Посетил банк. Надо бы пересчитать."
T["Die Bannliste ist leer."] = "Список банов пуст."
T["Die Chat-Eingabe war von Oasis beruehrt (z.B. 'Anfluestern'-Knopf), danach wurde /target eingegeben."] = "Строка чата была затронута Oasis (напр. кнопка «Шепнуть»), затем введено /target."
T["Die Chat-Eingabe war von Oasis beruehrt (z.B. 'Anfluestern'-Knopf), danach wurde dort ein /cast-Befehl eingegeben."] = "Строка чата была затронута Oasis (напр. кнопка «Шепнуть»), затем там введена команда /cast."
T["Die Chat-Eingabe war von Oasis beruehrt, danach wurde /focus eingegeben."] = "Строка чата была затронута Oasis, затем введено /focus."
T["Die Chat-Eingabe war von Oasis beruehrt, danach wurde ein Zauber-Befehl eingegeben."] = "Строка чата была затронута Oasis, затем введена команда заклинания."
T["Die Dungeonkarten haben keine Koordinaten. Klick hier, dann auf die Stelle der Karte, an der du gerade stehst. An zwei weit entfernten Stellen gemacht, zeigt Oasis dich und deine Gruppe auf der Karte - fuer die ganze Gilde."] = "У карт подземелий нет координат. Щёлкни здесь, затем по месту на карте, где стоишь. Сделав это в двух удалённых точках, Oasis покажет тебя и твою группу на карте - для всей гильдии."
T["Die Gilde bekommt Bescheid"] = "Гильдия получит уведомление"
T["Die Gilde sieht dabei, wem du antwortest. Standard: aus"] = "Гильдия при этом видит, кому ты отвечаешь. По умолчанию: выкл."
T["Die Gilde sieht dein Feuer %d Minuten auf der Karte."] = "Гильдия видит твой костёр на карте %d мин."
T["Die Gilde sieht in der Chronik, was du erreicht hast"] = "Гильдия видит в хронике, чего ты достиг"
T["Die Gilde sucht gerade nichts aus diesem Dungeon."] = "Гильдия сейчас ничего не ищет из этого подземелья."
T["Die Gilde vergibt noch keine Beute-Punkte - deine Werte erscheinen, sobald die Raidleitung einen Raid startet."] = "Гильдия ещё не выдаёт очки добычи - твои значения появятся, когда руководство рейда запустит рейд."
T["Die Gildenbank wurde noch nicht gelesen"] = "Банк гильдии ещё не прочитан"
T["Die Gildenleitung benennt Schlachtzugsleiter und Assistenz unter Krone > Module > Raids & Beute (Namen oder ab Gildenrang). Im laufenden Raid zaehlen auch Raidleiter und Assistenten."] = "Руководство гильдии назначает лидеров и помощников рейда в разделе Корона > Модули > Рейды и добыча (по имени или с звания). В текущем рейде учитываются также лидер и помощники рейда."
T["Die Gildenleitung benennt Schlachtzugsleiter unter Krone > Module > Raids & Beute. Im laufenden Raid zaehlen auch Raidleiter und Assistenten."] = "Руководство гильдии назначает лидеров рейда в разделе Корона > Модули > Рейды и добыча. В текущем рейде учитываются также лидер и помощники рейда."
T["Die Gildenleitung benennt Schlachtzugsleiter unter Krone > Module > Raids & Beute. Im laufenden Raid zaehlt auch der Raidleiter."] = "Руководство гильдии назначает лидеров рейда в разделе Корона > Модули > Рейды и добыча. В текущем рейде учитывается также лидер рейда."
T["Die Gildenleitung erlaubt Gruppensuchen erst ab einem hoeheren Rang."] = "Руководство гильдии разрешает поиск группы только с более высокого звания."
T["Die Gildenleitung erlaubt Umfragen erst ab einem hoeheren Rang."] = "Руководство гильдии разрешает опросы только с более высокого звания."
T["Die Gildenleitung hat die Mitstreiter-Suche abgeschaltet."] = "Руководство гильдии отключило поиск соратников."
T["Die Gildenleitung hat offene Einladungen abgeschaltet - fordere jemanden direkt heraus."] = "Руководство гильдии отключило открытые приглашения - вызови кого-нибудь напрямую."
T["Die Gildenleitung legt unter Krone > Module fest, welche Raenge das duerfen."] = "Руководство гильдии задаёт в Корона > Модули, каким званиям это можно."
T["Die Gildensuche von WoW hilft beim Finden - neutral, ohne Werbung."] = "Поиск гильдий WoW поможет найти - нейтрально, без рекламы."
T["Die Grenze legt nur der Gildenmeister fest. Rang 1 = Gildenmeister."] = "Предел задаёт только глава гильдии. Звание 1 = глава гильдии."
T["Die Knoepfe schreiben den Befehl in die Chatzeile - erst mit Enter wird er ausgefuehrt."] = "Кнопки вписывают команду в строку чата - она выполнится только по Enter."
T["Die Kuerzel stehen auch in WoWs Tastaturbelegung unter AddOns > Oasis. Esc schliesst das Oasis-Fenster (im Kampf nicht - dort gehoert Esc dem Spiel)."] = "Сочетания есть и в назначении клавиш WoW: AddOns > Oasis. Esc закрывает окно Oasis (не в бою - там Esc принадлежит игре)."
T["Die Kuerzel stehen auch in WoWs Tastaturbelegung unter AddOns > Oasis. Esc schliesst das Oasis-Fenster, solange du zuletzt hineingeklickt hast."] = "Сочетания есть и в назначении клавиш WoW: AddOns > Oasis. Esc закрывает окно Oasis, если ты последним щёлкнул в нём."
T["Die Leiste rollt nach oben weg; Maus an den oberen Rand und sie kommt herunter (nur wenn sie oben angedockt ist)"] = "Панель уезжает вверх; подведи мышь к верхнему краю, и она опустится (только если закреплена вверху)"
T["Die Reservierungs-Zeile erscheint nur, wenn du in einer Gruppe oder einem Schlachtzug bist"] = "Строка резерва появляется только в группе или рейде"
T["Die Waechter der Sande"] = "Стражи Песков"
T["Die Weltkarte geoeffnet. Wo war nochmal Norden?"] = "Открыл карту мира. Где там был север?"
T["Die echte Leiste oben zeigt jede Aenderung sofort"] = "Настоящая панель вверху сразу показывает каждое изменение"
T["Die ersten 20 Ausdauer geben je 1, jeder weitere Punkt 10 Gesundheit."] = "Первые 20 выносливости дают по 1, каждое следующее очко - 10 здоровья."
T["Die meisten Geisterlaeufe der Gilde. Der Friedhof hat eine Bank mit deinem Namen."] = "Больше всех пробежек призраком в гильдии. На кладбище есть скамейка с твоим именем."
T["Die meisten Screenshots der Gilde"] = "Больше всех скриншотов в гильдии"
T["Die meisten Tode der letzten 7 Tage"] = "Больше всех смертей за 7 дн."
T["Die meisten vollen Taschen der Gilde"] = "Чаще всех полные сумки в гильдии"
T["Die neueste Durchsage steht 3 Tage oben auf der Uebersicht."] = "Последнее объявление 3 дня висит вверху обзора."
T["Die vergessenen Teiche"] = "Забытые пруды"
T["Diese Abzeichen zeigt deine Profilkarte zuerst - bei dir und bei der Gilde."] = "Эти значки твоя карточка профиля показывает первыми - у тебя и у гильдии."
T["Diese Hinweise ausschalten"] = "Выключить эти подсказки"
T["Diese Quest hat %s, nicht du."] = "Это задание у %s, не у тебя."
T["Diese Quest ist nicht in deinem Questlog."] = "Этого задания нет в твоём журнале."
T["Diese Regel gibt es schon."] = "Такое правило уже есть."
T["Diese Seiten stehen als kleine Knoepfe in der eingeklappten Oasis-Leiste - ein Klick oeffnet sie direkt."] = "Эти страницы видны маленькими кнопками на свёрнутой панели Oasis - щелчок сразу открывает их."
T["Diese Sitzung: %d EP in %s"] = "Этот сеанс: %d опыта за %s"
T["Diese Sprache gilt nach dem naechsten /reload - hier klicken zum Neuladen."] = "Язык применится после следующего /reload - щёлкни здесь для перезагрузки."
T["Diese Taktik ist noch leer."] = "Эта тактика пока пуста."
T["Diese Woche ist noch alles offen - wer macht den Anfang?"] = "На этой неделе всё ещё открыто - кто первый?"
T["Diese Woche:"] = "На этой неделе:"
T["Dieser Client hat keine Sammlungs-Schnittstelle. /oa probe sammlung zeigt Details."] = "У этого клиента нет интерфейса коллекций. /oa probe sammlung покажет детали."
T["Dieser Client liefert keine Rufdaten - du siehst nur die Staende der anderen."] = "Этот клиент не выдаёт данные репутации - видны только значения других."
T["Dieser Client meldet keine seltenen Gegner (Schnittstelle fehlt). /oa probe rares zeigt Details."] = "Этот клиент не сообщает о редких противниках (нет интерфейса). /oa probe rares покажет детали."
T["Dir fehlt nichts, was die Gilde hat - stark!"] = "У тебя есть всё, что есть у гильдии - отлично!"
T["Dir selbst etwas zugefluestert. Wer sonst hoert dir so gut zu?"] = "Шепнул сам себе. Кто ещё так хорошо слушает?"
T["Discord-Bruecke: Ist sie an, speichert WoW den ganzen Chat (auch Fluestern) im Klartext in Logs/WoWChatLog.txt."] = "Мост Discord: если включён, WoW сохраняет весь чат (и шепот) открытым текстом в Logs/WoWChatLog.txt."
T["Discord-Link"] = "Ссылка Discord"
T["Discord-Link - z.B. discord.gg/deinegilde (Enter speichert)"] = "Ссылка Discord - напр. discord.gg/вашагильдия (Enter сохраняет)"
T["Discord-Nachrichten im Gildenchat zeigen (ueber OasisSync, nach /reload)"] = "Показывать сообщения Discord в чате гильдии (через OasisSync, после /reload)"
T["Discord-Nachrichten uebernommen: %d (neue erscheinen erst nach /reload)"] = "Сообщений Discord перенесено: %d (новые появятся после /reload)"
T["Diskoball"] = "Диско-шар"
T["Distanz"] = "Дальний бой"
T["Distanz-Angriffskraft"] = "Сила атаки дальнего боя"
