T["Doppelte Oasis-XP fuer alle in der Gilde. Alle mit Oasis bekommen eine Durchsage."] = "Двойной опыт Oasis для всей гильдии. Все с Oasis получат объявление."
T["Doppelter Rechtsklick wirft aus, Fang-Statistik in der Uebersicht"] = "Двойной ПКМ забрасывает удочку, статистика улова в обзоре"
T["Doppelter Rechtsklick wirft die Angel aus (Angel muss angelegt sein)."] = "Двойной ПКМ забрасывает удочку (удочка должна быть надета)."
T["Double XP"] = "Двойной опыт"
T["Double XP laeuft"] = "Двойной опыт активен"
