T["Drachenfeueramulett"] = "Амулет драконьего огня"
T["Dreieck"] = "Треугольник"
T["Dreieck = Kopfnuss (Schurke)"] = "Треугольник = Ошеломление (разбойник)"
T["Dschungel"] = "Джунгли"
T["Du bist Plundermeister - die Regeln greifen."] = "Ты ответственный за добычу - правила действуют."
T["Du bist auf Platz %d"] = "Ты на %d-м месте"
T["Du bist der beste in der Gilde!"] = "Ты лучший в гильдии!"
