T["Noch keine Abklingzeiten geteilt - wer Transmutation, Mondstoff oder einen Salzstreuer hat, erscheint hier."] = "Пока никто не поделился временем восстановления - здесь появятся те, у кого есть трансмутация, луноткань или солонка."
T["Noch keine Abzeichen"] = "Пока нет значков"
T["Noch keine Ausruestung bekannt - Spieler in der Naehe anvisieren und betrachten (Oasis betrachtet Mitspieler in der Gruppe automatisch)."] = "Экипировка пока неизвестна - возьми ближайших игроков в цель и осмотри (Oasis осматривает соигроков в группе автоматически)."
T["Noch keine Berufe gelernt."] = "Профессии ещё не изучены."
T["Noch keine Beute aus diesem Dungeon im Gilden-Log."] = "В журнале гильдии ещё нет добычи из этого подземелья."
T["Noch keine Beute erfasst"] = "Добыча ещё не записана"
T["Noch keine Bewerber. Name oben eintragen - Klick auf den Status schaltet weiter."] = "Пока нет кандидатов. Введи имя выше - щелчок по статусу переключает его."
T["Noch keine Daten - Ausruestung kommt mit dem naechsten Abgleich der Oasis-Nutzer."] = "Пока нет данных - экипировка придёт при следующей сверке пользователей Oasis."
T["Noch keine Daten - Mitglieder schicken ihre Messung alle 15 Min (ab dieser Version)."] = "Пока нет данных - участники отправляют замер каждые 15 мин. (с этой версии)."
T["Noch keine Daten - oeffne einmal das Sammlungsfenster oder trage Reittiere und Haustiere in der Tasche. Sobald Gildenmitglieder mit Oasis online sind, erscheinen sie hier."] = "Пока нет данных - открой разок окно коллекций или носи верховых животных и питомцев в сумке. Члены гильдии с Oasis появятся здесь, когда будут в сети."
T["Noch keine Daten von der Gilde."] = "Пока нет данных от гильдии."
T["Noch keine Daten. Sobald Gildenmitglieder mit Oasis einloggen, erscheinen ihre Raid-IDs hier."] = "Пока нет данных. Как только члены гильдии войдут с Oasis, их сохранения рейдов появятся здесь."
T["Noch keine Dungeon-Laeufe aufgezeichnet."] = "Прохождения подземелий ещё не записаны."
T["Noch keine Dungeons geplant."] = "Подземелья ещё не запланированы."
T["Noch keine Eintraege."] = "Записей пока нет."
T["Noch keine Emojis benutzt - Favoriten aus der Emoji-Auswahl erscheinen hier."] = "Эмодзи ещё не использовались - избранное из выбора эмодзи появится здесь."
T["Noch keine Favoriten - Diamant anklicken."] = "Пока нет избранного - щёлкни ромб."
T["Noch keine Favoriten - Stern oder Rechtsklick auf einen Sound."] = "Пока нет избранного - звёздочка или ПКМ по звуку."
T["Noch keine Favoriten.\nRechtsklick auf ein Emoji merkt es hier."] = "Пока нет избранного.\nПКМ по эмодзи сохранит его здесь."
T["Noch keine Fluesternachrichten."] = "Сообщений шепотом пока нет."
T["Noch keine Fluesternachrichten. Schreib jemandem aus der Gilde!"] = "Сообщений шепотом пока нет. Напиши кому-нибудь из гильдии!"
T["Noch keine Fraktionen entdeckt."] = "Фракции ещё не открыты."
T["Noch keine Gildenziele. Lege das erste an - z. B. eine legendaere Waffe oder Material fuer den Raid."] = "Пока нет целей гильдии. Создай первую - напр. легендарное оружие или материалы для рейда."
T["Noch keine Kampfberichte. Nach dem ersten Bosskampf steht hier jeder Versuch - mit Zeitstrahl der Tode und wiederkehrenden Mustern."] = "Пока нет отчётов о боях. После первого боя с боссом здесь будет каждая попытка - с хронологией смертей и повторяющимися закономерностями."
T["Noch keine Kampfberichte. Nach dem ersten Bosskampf steht hier jeder Versuch."] = "Пока нет отчётов о боях. После первого боя с боссом здесь будет каждая попытка."
T["Noch keine Kandidaten. Spiel mit Leuten ausserhalb der Gilde - wer ohne Gilde ist und gut bewertet wird, landet hier."] = "Пока нет кандидатов. Играй с людьми вне гильдии - кто без гильдии и хорошо оценён, попадёт сюда."
T["Noch keine Kombos.\nShift+Klick auf mehrere Emojis, dann Merken."] = "Пока нет комбо.\nShift+щелчок по нескольким эмодзи, затем «Запомнить»."
T["Noch keine Kontakte. Geh mit anderen Oasis-Nutzern in eine Gruppe - Oasis merkt sie sich dann hier, auch ohne Gilde."] = "Пока нет контактов. Вступи в группу с другими пользователями Oasis - Oasis запомнит их здесь, даже без гильдии."
T["Noch keine Meilensteine. Level auf, lern Berufe - hier entsteht deine Geschichte."] = "Пока нет рубежей. Качайся, учи профессии - здесь начнётся твоя история."
T["Noch keine Meldungen aus der Gilde."] = "Пока нет сообщений из гильдии."
T["Noch keine Momente - spiel einfach, Oasis schreibt mit."] = "Пока нет моментов - просто играй, Oasis всё записывает."
T["Noch keine Nachrichten im Offizierschat. Alles, was ab jetzt im Kanal /o geschrieben wird, steht hier."] = "В офицерском чате пока нет сообщений. Всё, что с этого момента пишется в канале /o, будет здесь."
T["Noch keine Positionen - die Karte fuellt sich, sobald Mitglieder mit Oasis unterwegs sind."] = "Пока нет позиций - карта заполнится, когда участники с Oasis будут в пути."
T["Noch keine Preise. Sobald jemand mit Midas im AH scannt, stehen sie hier."] = "Пока нет цен. Как только кто-то просканирует аукцион с Midas, они появятся здесь."
T["Noch keine Profile gespeichert."] = "Профили ещё не сохранены."
T["Noch keine Punkte"] = "Пока нет очков"
T["Noch keine Raidtage erfasst. Der Raidleiter (mit Oasis) schreibt sie bei jedem Boss-Kill automatisch mit."] = "Рейдовые дни ещё не записаны. Лидер рейда (с Oasis) записывает их автоматически при каждом убийстве босса."
T["Noch keine Regeln"] = "Пока нет правил"
T["Noch keine Regeln. Nimm eine Schnell-Vorlage oder leg oben eine eigene an."] = "Пока нет правил. Возьми быстрый шаблон или создай своё выше."
T["Noch keine Rufdaten. Sie kommen automatisch, sobald Mitglieder mit Oasis online sind."] = "Пока нет данных репутации. Они придут автоматически, когда участники с Oasis будут в сети."
T["Noch keine Sammlung geteilt. Sobald Gildenmitglieder mit Oasis online sind, erscheinen sie hier."] = "Пока никто не поделился коллекцией. Они появятся здесь, когда члены гильдии с Oasis будут в сети."
T["Noch keine Sets."] = "Пока нет комплектов."
T["Noch keine Sichtung. Sobald jemand mit Oasis einen seltenen Gegner sieht, steht er hier."] = "Пока никого не замечено. Как только кто-то с Oasis увидит редкого противника, он появится здесь."
T["Noch keine Spielzeiten bekannt. Oasis lernt mit jedem Abend, an dem du online bist - und uebernimmt die Profile der anderen."] = "Игровое время пока неизвестно. Oasis учится каждый вечер, когда ты в сети, - и перенимает профили других."
T["Noch keine Suche. Level eingeben und \"Suchen\" klicken - Spieler mit Gilde werden ausgeblendet."] = "Поиска ещё не было. Введи уровни и нажми \"Искать\" - игроки с гильдией скрываются."
T["Noch keine Taktiken."] = "Пока нет тактик."
T["Noch keine Taktiken. Die Raidleitung kann je Boss eine kurze Taktik anlegen - alle sehen sie hier und bekommen sie beim Anvisieren angezeigt."] = "Пока нет тактик. Руководство рейда может создать короткую тактику на каждого босса - все видят её здесь и при взятии босса в цель."
T["Noch keine Talente bekannt. Mitglieder mit Oasis teilen sie automatisch; andere Spieler: anvisieren und betrachten (Rechtsklick > Betrachten) oder hier mit Ziel erneut oeffnen."] = "Таланты пока неизвестны. Участники с Oasis делятся ими автоматически; других игроков возьми в цель и осмотри (ПКМ > Осмотреть) или открой здесь снова с целью."
T["Noch keine Vergaben - sie erscheinen hier, sobald die Raidleitung Beute verteilt."] = "Пока нет выдач - они появятся здесь, когда руководство рейда раздаст добычу."
T["Noch keine Werte - nach dem naechsten Kampf erscheint hier, wer vorne liegt."] = "Пока нет значений - после следующего боя здесь появится, кто впереди."
T["Noch keine Wunschtage - tippe an, wann du kannst."] = "Пока нет желаемых дней - отметь, когда можешь."
T["Noch keine Wunschtage gemeldet."] = "Желаемые дни пока не указаны."
T["Noch keine Ziele. Leg oben eins an - Oasis hakt es automatisch ab."] = "Пока нет целей. Создай выше - Oasis отметит автоматически."
T["Noch keine Zusagen - sei der Erste!"] = "Пока нет записей - будь первым!"
T["Noch keine eigene Beute"] = "Своей добычи пока нет"
T["Noch keine eigene Beute erfasst (ab Qualitaet 'Selten', einstellbar)."] = "Своя добыча ещё не записана (от качества «Редкий», настраивается)."
T["Noch nicht angemeldet - waehle unten deine Rolle"] = "Ещё не записан - выбери роль ниже"
T["Noch nicht bereit"] = "Ещё не готов"
T["Noch nicht fuer die Gilde uebernommen:"] = "Ещё не применено для гильдии:"
T["Noch nicht kalibriert - Kalibrieren?"] = "Ещё не откалибровано - калибровать?"
T["Noch nichts auf der Wunschliste.\nTrag oben ein, was du brauchst - alle mit Oasis sehen es im Tooltip und beim Looten."] = "В списке желаний пока пусто.\nДобавь выше, что тебе нужно - все с Oasis увидят это в подсказках и при добыче."
T["Noch nichts aufgezeichnet."] = "Пока ничего не записано."
T["Noch nichts benutzt."] = "Пока ничего не использовано."
T["Noch nichts blockiert. Sobald WoW Oasis blockiert, steht hier welche Funktion und was Oasis kurz vorher gemacht hat."] = "Пока ничего не заблокировано. Как только WoW заблокирует Oasis, здесь будет видно, какая функция и что Oasis делал перед этим."
T["Noch nichts eingelesen"] = "Пока ничего не прочитано"
T["Noch nichts geangelt."] = "Пока ничего не поймано."
T["Noch nichts gemerkt - Rechtsklick auf eine Nachricht: Nachricht merken."] = "Пока ничего не сохранено - ПКМ по сообщению: Сохранить сообщение."
T["Noch nichts passiert - zieht los und schreibt Geschichte!"] = "Пока ничего не произошло - отправляйся творить историю!"
T["Noch nichts reserviert"] = "Пока ничего не зарезервировано"
T["Noch nichts reserviert - ein Item pro Termin."] = "Пока ничего не зарезервировано - один предмет на событие."
T["Noch nichts reserviert."] = "Пока ничего не зарезервировано."
T["Noch nichts verkauft."] = "Пока ничего не продано."
T["Noch nichts verteilt. Sobald eine Regel greift, steht es hier."] = "Пока ничего не выдано. Как только сработает правило, это появится здесь."
T["Noch nie direkt mit dir abgeglichen"] = "Ещё ни разу не сверялся с тобой напрямую"
T["Noch niemand angefluestert."] = "Ты ещё никому не шептали."
T["Noch niemand aus der Gilde hat es uebrig."] = "Пока ни у кого в гильдии нет лишнего."
T["Noch niemand aus der Gilde mit deiner Spezialisierung teilt seine Talente (Oasis-Nutzer teilen automatisch)."] = "Пока никто в гильдии с твоей специализацией не делится талантами (пользователи Oasis делятся автоматически)."
T["Noch niemand gegangen, seit Oasis mitschreibt."] = "Никто не уходил, с тех пор как Oasis ведёт запись."
T["Noch niemand gemeldet - sei der Erste!"] = "Пока никто не записался - будь первым!"
T["Noch niemand sonst kennt das Rezept."] = "Больше никто пока не знает этот рецепт."
T["Noch niemand teilt seine Handelsbilanz."] = "Пока никто не делится торговым балансом."
T["Noch niemand teilt seine Handelsbilanz. Unten 'Bilanz teilen' einschalten - dann geht's los."] = "Пока никто не делится торговым балансом. Включи ниже «Делиться итогом» - и начнём."
T["Noch teilt niemand mit Oasis handelbare Teile. Je mehr Mitglieder Oasis nutzen, desto voller wird es hier."] = "Пока никто с Oasis не делится передаваемыми предметами. Чем больше участников используют Oasis, тем полнее здесь."
T["Noch zu uebergeben"] = "Ещё передать"
T["Noch zu wenig Daten fuer eine Stosszeit"] = "Пока мало данных для часа пик"
T["Normal"] = "Обычно"
T["Normal meldet Oasis nur Suchen, die du selbst noch offen hast"] = "Обычно Oasis сообщает только о поисках, которые у тебя самого ещё открыты"
T["Notiz (Klasse, Kontakt, Eindruck ...)"] = "Заметка (класс, контакт, впечатление ...)"
T["Notiz an den Plundermeister (optional)"] = "Заметка ответственному за добычу (необяз.)"
T["Notiz der Gildenleitung"] = "Заметка руководства гильдии"
T["Notiz von %s: %s"] = "Заметка от %s: %s"
T["Notiz zu %s"] = "Заметка о %s"
T["Notiz zur Person"] = "Заметка об игроке"
T["Notiz zur Suche (Zeit, Treffpunkt) ..."] = "Заметка к поиску (время, место сбора) ..."
T["Notizen sehen und schreiben nur Offiziere."] = "Заметки видят и пишут только офицеры."
T["Nur %s"] = "Только %s"
T["Nur Abende vorschlagen"] = "Предлагать только вечера"
T["Nur Banner und drei Spalten (wer ist online, was passiert, als Naechstes) - ohne Kacheln und Highlight-Zeile"] = "Только баннер и три колонки (кто в сети, что происходит, далее) - без плиток и строки событий"
T["Nur Dungeons, deren Beute besser ist als deine angelegte Ausruestung."] = "Только подземелья, где добыча лучше твоей надетой экипировки."
T["Nur Eintraege dieser Person"] = "Только записи этого игрока"
T["Nur Farbverlauf"] = "Только градиент"
T["Nur Gegner im Kampf"] = "Только противники в бою"
T["Nur Gildenleitung"] = "Только руководство гильдии"
T["Nur Gruppenquests beruecksichtigen"] = "Учитывать только групповые задания"
T["Nur Lagerfeuer in meinem Gebiet melden"] = "Сообщать только о кострах в моей зоне"
T["Nur Mains ab Level"] = "Только основные с уровня"
T["Nur Mitglieder bis zu diesem Rang duerfen eine Gruppensuche starten (10 = alle)."] = "Только участники до этого звания могут начать поиск группы (10 = все)."
T["Nur Mitglieder bis zu diesem Rang duerfen eine neue Umfrage starten (10 = alle)."] = "Только участники до этого звания могут начать новый опрос (10 = все)."
T["Nur Mitglieder mit Oasis. Geteilt werden offene Questitems, uebrige Questitems und teilbare Quests."] = "Только участники с Oasis. Делятся открытыми и лишними предметами заданий и заданиями, которыми можно поделиться."
T["Nur Oasis-Spieler"] = "Только игрокам с Oasis"
T["Nur Oasis-Spieler: jeder sieht sie in seiner eigenen Sprache."] = "Только игрокам с Oasis: каждый видит на своём языке."
T["Nur Offiziere und Gildenleitung sehen diesen Kanal (/o)."] = "Этот канал (/o) видят только офицеры и руководство гильдии."
T["Nur Plundermeister, Anfuehrer oder Assistenten koennen verteilen."] = "Раздавать могут только ответственный за добычу, лидер или помощники."
T["Nur Rezepte, die du selbst kannst"] = "Только рецепты, которые знаешь ты"
T["Nur Rezepte, die gerade jemand online herstellen kann"] = "Только рецепты, которые кто-то в сети может изготовить сейчас"
T["Nur Upgrades"] = "Только улучшения"
T["Nur an die eigene Gruppe, fuer die Dungeon-Karte"] = "Только своей группе, для карты подземелья"
T["Nur ansehen - bearbeiten: Leitung, Schlachtzugsleiter, Raid-Assistenten"] = "Только просмотр - править: руководство, лидеры рейда, помощники рейда"
T["Nur ansehen - zeichnen darf der Raidleiter"] = "Только просмотр - рисует лидер рейда"
T["Nur auf diesem PC"] = "Только на этом ПК"
T["Nur ausgeblendet - klick hier, um zurueckzukehren."] = "Только скрыто - щёлкни здесь, чтобы вернуться."
T["Nur bei dir"] = "Только у тебя"
T["Nur bei dir gespeichert"] = "Хранится только у тебя"
T["Nur bei gleicher Klasse und Spezialisierung."] = "Только при том же классе и специализации."
T["Nur das Noetigste"] = "Только самое нужное"
T["Nur der Gildenmeister kann das aendern."] = "Изменить может только глава гильдии."
T["Nur der Gildenmeister, hoechstens 10 Raenge."] = "Только глава гильдии, не более 10 званий."
T["Nur der Gruppenleiter kann eine Suche starten."] = "Начать поиск может только лидер группы."
T["Nur der Gruppenleiter kann suchen"] = "Искать может только лидер группы"
T["Nur die Gildenleitung kann das aendern."] = "Изменить может только руководство гильдии."
T["Nur die Gildenleitung kann die Deathroll-Rangliste zuruecksetzen."] = "Сбросить рейтинг Deathroll может только руководство гильдии."
T["Nur die wichtigsten Bereiche sind an."] = "Включены только самые важные разделы."
T["Nur diese Person hoert ihn (wenn sie Oasis hat)."] = "Его слышит только этот игрок (если у него есть Oasis)."
T["Nur diesen Abschnitt posten"] = "Опубликовать только этот раздел"
T["Nur fehlende"] = "Только недостающие"
T["Nur fuer Anfuehrer und Assistenten"] = "Только для лидера и помощников"
T["Nur fuer Offiziere"] = "Только для офицеров"
T["Nur fuer Schlachtzugsleiter"] = "Только для лидеров рейда"
T["Nur fuer Schlachtzugsleiter & Assistenz"] = "Только для лидеров и помощников рейда"
T["Nur fuer Umfragen, die du gestartet oder bei denen du abgestimmt hast"] = "Только для опросов, которые ты начал или где голосовали"
T["Nur fuer den Schlachtzugsleiter"] = "Только для лидера рейда"
T["Nur fuer dich sichtbar - steht im Kopf des Gespraechs mit %s."] = "Видно только тебе - отображается в шапке беседы с %s."
T["Nur fuer dich: nach dem Kampf eine Zeile mit Dauer und erstem Tod"] = "Только для тебя: после боя строка с длительностью и первой смертью"
T["Nur fuer die Fehlersuche. Standard: aus"] = "Только для поиска ошибок. По умолчанию: выкл."
T["Nur fuer die Gildenleitung"] = "Только для руководства гильдии"
T["Nur fuers Aussehen"] = "Только для внешнего вида"
T["Nur guenstig"] = "Только дешёвые"
T["Nur handelbare (nicht seelengebundene) Teile. Werte nach Klasse und Rolle wie beim Verbesserungs-Pfeil; Bank zaehlt erst nach einmal Oeffnen."] = "Только передаваемые (непривязанные) предметы. Оценка по классу и роли как у стрелки улучшения; банк учитывается после первого открытия."
T["Nur in der offenen Welt; kann viele Eintraege erzeugen"] = "Только в открытом мире; может создать много записей"
T["Nur in einer Gruppe und mit der Quest im Log."] = "Только в группе и с заданием в журнале."
T["Nur in einer Gruppe."] = "Только в группе."
T["Nur mein Gebiet"] = "Только моя зона"
T["Nur meine"] = "Только мои"
T["Nur mit Helfern"] = "Только с помощниками"
T["Nur mit Upgrades"] = "Только с улучшениями"
T["Nur neue"] = "Только новые"
T["Nur offene Challenges, die zu deinen Charakteren passen (Klassen, Berufe) - plus alle Dungeons, Raids, PvP und Abenteuer."] = "Только открытые испытания, подходящие твоим персонажам (классы, профессии) - плюс все подземелья, рейды, PvP и приключения."
T["Nur ohne Belohnungs-Auswahl und ohne Kosten. Shift = aussetzen."] = "Только без выбора награды и без затрат. Shift = пропустить."
T["Nur online"] = "Только в сети"
T["Nur von Leitern, bei denen du ueber Oasis angefragt hast"] = "Только от лидеров, к которым ты обращался через Oasis"
T["Nur von Oasis-Nutzern"] = "Только от пользователей Oasis"
