T["Oasis antwortet automatisch auf pc / preis mit Item-Link im Gildenchat"] = "Oasis автоматически отвечает на pc / preis со ссылкой на предмет в чате гильдии"
T["Oasis begleitet %s ab heute (Stufe %d)"] = "Oasis сопровождает %s с сегодняшнего дня (%d ур.)"
