T["Oasis fasst deine Charaktere in der Gilde zu einem Spieler zusammen. Spaeter aenderbar unter Einstellungen > Profil & Sichern."] = "Oasis объединяет твоих персонажей в гильдии в одного игрока. Изменить позже: Настройки > Профиль и резервирование."
T["Oasis funktioniert trotzdem fuer dich: dein Profil, Ziele, Dungeons und Sammlungen sind da."] = "Oasis всё равно работает для тебя: твой профиль, цели, подземелья и коллекции на месте."
T["Oasis hatte Blizzard-Knoepfe (Aktionsleisten, Taschen, Tooltip, Chat) beruehrt (ab 0.5.504 behoben - bitte Oasis aktualisieren)."] = "Oasis затрагивал кнопки Blizzard (панели команд, сумки, подсказки, чат) (исправлено с 0.5.504 - обнови Oasis)."
T["Oasis ist bereit"] = "Oasis готов"
T["Oasis kann sehr viel. Waehle, was du nutzen willst - der Rest bleibt erstmal aus und laesst sich jederzeit unter 'Entdecken' einschalten."] = "Oasis умеет многое. Выбери, чем хочешь пользоваться - остальное пока выключено, его можно включить в любой момент в «Обзор»."
T["Oasis liest nach jedem Kampf Blizzards eingebaute Schadensanzeige - auch in Instanzen."] = "Oasis после каждого боя читает встроенный счётчик урона Blizzard - и в подземельях."
T["Oasis liest nach jedem Kampf Blizzards eingebaute Schadensanzeige - das Kampflog ist in WoW Forever fuer Addons gesperrt. Mitspieler brauchen Oasis ab 0.5.577. Werte, die Blizzard verschluesselt (z.B. in Instanzen), zaehlen nicht."] = "Oasis после каждого боя читает встроенный счётчик урона Blizzard - журнал боя в WoW Forever закрыт для аддонов. Соигрокам нужен Oasis от 0.5.577. Значения, которые Blizzard шифрует (напр. в подземельях), не учитываются."
T["Oasis oeffnen / schliessen"] = "Открыть / закрыть Oasis"
T["Oasis ohne Gilde"] = "Oasis без гильдии"
T["Oasis tauscht Daten nur mit Gildenmitgliedern, die Oasis auch haben. Im Kampf und in Instanzen pausiert der Austausch."] = "Oasis обменивается данными только с членами гильдии, у которых тоже есть Oasis. В бою и в подземельях обмен приостановлен."
T["Oasis tauscht realmweit Version und Fehlerberichte mit anderen Oasis-Nutzern aus."] = "Oasis обменивается версией и отчётами об ошибках с другими пользователями Oasis на сервере."
T["Oasis tauscht realmweit Version und Fehlerberichte mit anderen Oasis-Nutzern aus. Abschalten: Einstellungen > Profil & Sichern."] = "Oasis обменивается версией и отчётами об ошибках с другими пользователями Oasis на сервере. Выключить: Настройки > Профиль и резервирование."
T["Oasis warnt dich, wenn diese Person dir schreibt oder in deiner Gruppe ist."] = "Oasis предупредит, если этот игрок напишет тебе или будет в твоей группе."
