T["Was"] = "Что"
T["Was Oasis von der Gilde gerade kennt"] = "Что Oasis сейчас знает о гильдии"
T["Was andere Oasis-Nutzer von dir sehen"] = "Что другие пользователи Oasis видят о тебя"
