T["Was ist passiert? Je genauer, desto schneller ist es behoben. Die Meldung geht an den Entwickler von Oasis."] = "Что случилось? Чем точнее, тем быстрее исправят. Сообщение уйдёт разработчику Oasis."
T["Was jeder fuer diesen Raid dabei haben muss - gilt fuer die ganze Gilde."] = "Что каждый должен иметь с собой для этого рейда - для всей гильдии."
