T["Weltkarte aufdecken findest du unter Bereiche > Karte."] = "«Открыть карту мира» - в Разделы > Карта."
T["Weltkarte aufdecken findest du unter der Weltkarte und unter Bereiche > Karte."] = "«Открыть карту мира» - под картой мира и в Разделы > Карта."
T["Wen moechtest du herausfordern? Namen eingeben oder jemanden anvisieren."] = "Кого хочешь вызвать? Введи имя или возьми кого-нибудь в цель."
T["Wenn jemand etwas bei dir oder deinem Beruf bestellt (und wenn dein Auftrag fertig ist)"] = "Когда кто-то заказывает у тебя или твоей профессии (и когда твой заказ готов)"
T["Wenn jemand online kommt"] = "Когда кто-то входит в сеть"
T["Wer"] = "Кто"
T["Wer Daten schickt, die bei anderen abgelehnt werden (keine Rechte, gefaelschter Urheber, ausgedachte Eintraege). Ein unveraendertes Oasis tut das praktisch nie - ein Hinweis, kein Beweis."] = "Кто отправляет данные, которые у других отклоняются (нет прав, поддельный автор, выдуманные записи). Неизменённый Oasis так практически не делает - это подсказка, не доказательство."
T["Wer Interesse meldet, erscheint hier auf einem passenden Platz. Steht ein Termin, meldest du dich direkt auf der Karte an."] = "Кто заявит интерес, появится здесь на подходящем месте. Когда есть событие, записывайся прямо на карточке."
T["Wer aus der Gilde das Item auf der Wunschliste hat"] = "У кого в гильдии этот предмет в списке желаний"
T["Wer den Bereich in der Navigation sieht (die Gildenleitung sieht immer alles)"] = "Кто видит раздел в навигации (руководство видит всё всегда)"
T["Wer die Gilde verlassen hat oder entfernt wurde. Kommt jemand zurueck, meldet Oasis das der Gildenleitung."] = "Кто покинул гильдию или был исключён. Если кто-то вернётся, Oasis сообщит руководству гильдии."
T["Wer die Krone oben sieht. Ohne Rechte ist sie grau und oeffnet nur eine Vorschau."] = "Кто видит корону вверху. Без прав она серая и открывает только превью."
T["Wer eine Nachricht oben im Gildenchat anpinnen darf"] = "Кто может закреплять сообщение вверху чата гильдии"
T["Wer einladen darf, ist noch nicht bekannt - logge einmal mit deinem Main ein, dann merkt sich Oasis die Gildenleitung."] = "Кто может приглашать, пока неизвестно - зайди разок основным, и Oasis запомнит руководство гильдии."
T["Wer geht mit nach %s? Ich suche %s"] = "Кто со мной в %s? Ищу %s"
T["Wer hat ...?"] = "У кого есть ...?"
T["Wer hat das Questitem, das du brauchst? Und wem kannst du helfen?"] = "У кого есть нужный тебе предмет задания? И кому можешь помочь ты?"
T["Wer hat was bekommen"] = "Кто что получил"
T["Wer im Raid Punkte (Einsatz/Beute) buchen darf."] = "Кто может начислять очки (ставки/добыча) в рейде."
T["Wer in Gruppe oder Raid welche Buffs hat - und was noch fehlt"] = "У кого в группе или рейде какие баффы - и чего не хватает"
T["Wer ist bereit? Ampeln je Spieler"] = "Кто готов? Светофоры по игрокам"
T["Wer ist diese Woche schon gebunden, wer ist frei und freigeschaltet - Mains und Twinks"] = "Кто уже сохранён на этой неделе, кто свободен и с допуском - основные и твинки"
T["Wer ist online"] = "Кто в сети"
T["Wer ist online?"] = "Кто в сети?"
T["Wer ist wann online"] = "Кто когда в сети"
T["Wer ist wie weit"] = "Кто как далеко"
T["Wer kann was herstellen, Markt, Gildenbank"] = "Кто что изготавливает, рынок, банк гильдии"
T["Wer koennte mit: %s"] = "Кто мог бы пойти: %s"
T["Wer koennte mit?"] = "Кто мог бы пойти?"
T["Wer oft dabei ist und wenig bekommen hat, ist bei 'Bedarf' zuerst dran. Jede Woche verfaellt ein Teil der Punkte."] = "Кто часто участвует и мало получил, первым выбирает при «Нужно». Каждую неделю часть очков сгорает."
T["Wer sich mit passender Rolle meldet, wird sofort in deine Gruppe eingeladen."] = "Кто запишется с подходящей ролью, сразу будет приглашён в твою группу."
T["Wer steht wo bei welcher Fraktion? Kurz vor dem Ziel, gemeinsam farmen, Fortschritt dieser Woche"] = "Кто где стоит у какой фракции? Почти у цели, фармить вместе, прогресс этой недели"
T["Wer teilt am meisten aus, heilt am meisten, steckt am meisten ein?"] = "Кто наносит больше всех, лечит больше всех, получает больше всех?"
T["Wer zur Gildenleitung gehoert, legt der Gildenmeister unter Krone > Gilde fest."] = "Кто входит в руководство, задаёт глава гильдии в Корона > Гильдия."
T["Werbung"] = "Реклама"
T["Werte"] = "Характеристики"
T["Werte bringen deiner Rolle nichts"] = "характеристики бесполезны для твоей роли"
T["Werte nur zur Info"] = "характеристики только для справки"
T["Werte, Jahrbuch, Tagesziel, Rekorde und Abenteuer deines Charakters."] = "Характеристики, альбом, цель на день, рекорды и приключения твоего персонажа."
T["Werte: +Heilung, Intelligenz, Willenskraft, Mana-Reg.;Waffe: Stab oder Einhandwaffe + Nebenhand mit Heilung;Heilen: Verjuengung und Nachwachsen vorab, Heilende Beruehrung fuer grosse Treffer;Tipp: Anregen fuer Mana, Wiedergeburt fuer gefallene Heiler"] = "Характеристики: +исцеление, интеллект, дух, восст. маны;Оружие: посох или одноручное + левая рука с исцелением;Лечение: Омоложение и Восстановление заранее, Целительное прикосновение для сильных ударов;Совет: Озарение для маны, Возрождение для павших лекарей"
T["Werte: +Heilung, Intelligenz, Zauber-Krit (Erleuchtung gibt Mana zurueck), Mana-Reg.;Waffe: Einhandwaffe + Nebenhand/Schild mit Heilung;Heilen: Lichtblitz fuer kleinen Schaden, Heiliges Licht (niedriger Rang) fuer grosse Treffer;Tipp: Segen verteilen, Gottesschutz wenn du gezogen wirst"] = "Характеристики: +исцеление, интеллект, крит заклинаний (Просветление возвращает ману), восст. маны;Оружие: одноручное + левая рука/щит с исцелением;Лечение: Вспышка Света для малого урона, Свет небес (низкий ранг) для сильных ударов;Совет: раздавай благословения, Божественная защита, если на тебя агро"
T["Werte: +Heilung, Mana-Reg. (MP5), Intelligenz - Willenskraft bringt wenig;Waffe: Einhandwaffe + Schild mit Heilung;Heilen: Kettenheilung fuer Gruppen, Welle der Heilung (niedriger Rang) fuer den Tank;Tipp: Manaquelle-Totem stellen, Erdschild auf den Tank"] = "Характеристики: +исцеление, восст. маны (MP5), интеллект - дух даёт мало;Оружие: одноручное + щит с исцелением;Лечение: Цепное исцеление для групп, Волна исцеления (низкий ранг) для танка;Совет: ставь Тотем источника маны, Щит земли на танка"
T["Werte: +Heilung, Willenskraft (Meditation: Regeneration auch beim Zaubern), Intelligenz, Mana-Reg.;Waffe: Stab oder Einhandwaffe + Nebenhand mit Heilung, Zauberstab;Heilen: Erneuerung und Machtwort: Schild vorab, Grosse Heilung (niedriger Rang) fuer den Tank;Tipp: Gebet der Heilung fuer die Gruppe, Verblassen bei Aggro"] = "Характеристики: +исцеление, дух (Медитация: восстановление и при чтении), интеллект, восст. маны;Оружие: посох или одноручное + левая рука с исцелением, жезл;Лечение: Обновление и Слово силы: Щит заранее, Великое исцеление (низкий ранг) для танка;Совет: Молитва исцеления для группы, Уход в тень при агро"
T["Werte: Ruestung (Baerengestalt vervielfacht sie), Ausdauer, Beweglichkeit (Ausweichen + Ruestung);Waffe: egal fuer den Schaden - nur die Werte zaehlen (Stab/Stangenwaffe mit Ausdauer);Rotation: Zermalmen, Prankenhieb fuer Gruppen, Demoralisierendes Gebruell;Tipp: Staerke fuer mehr Bedrohung, Wutanfall zum Start"] = "Характеристики: броня (облик медведя её умножает), выносливость, ловкость (уклонение + броня);Оружие: урон неважен - важны только характеристики (посох/древковое с выносливостью);Ротация: Трёпка, Размах для групп, Деморализующий рёв;Совет: сила для угрозы, Исступление на старте"
T["Werte: Staerke (1 Punkt = 2 AP), Beweglichkeit (AP + Krit), Krit, Treffer bis +9 %;Waffe: egal fuer den Schaden - nur die Werte zaehlen;Rotation: Krallenhieb/Schreddern fuer Combopunkte, dann Wilder Biss;Tipp: Machtwandel (Gestalt neu) fuer Energie, aus dem Schleichen anspringen"] = "Характеристики: сила (1 очко = 2 СА), ловкость (СА + крит), крит, меткость до +9 %;Оружие: урон неважен - важны только характеристики;Ротация: Цапнуть/Полоснуть для приёмов серии, затем Свирепый укус;Совет: смена облика ради энергии, нападение из незаметности"
T["Werte: Staerke (1 Punkt = 2 AP), Krit (loest Schlaghagel aus = schneller schlagen), Treffer bis +9 %;Waffe: langsame Zweihandwaffe - Windzorn trifft pro Schlag, also je langsamer desto mehr Schaden;Rotation: Windzorn-Waffe, Sturmschlag, Erdschock;Tipp: Totem der Staerke der Erde und Windzorn-Totem fuer die Gruppe"] = "Характеристики: сила (1 очко = 2 СА), крит (вызывает Шквал = быстрее удары), меткость до +9 %;Оружие: медленное двуручное - Неистовство ветра срабатывает за удар, чем медленнее, тем больше урона;Ротация: Оружие неистовства ветра, Удар бури, Земной шок;Совет: Тотем силы земли и Тотем неистовства ветра для группы"
T["Werte: Staerke (1 Punkt = 2 AP), Krit, Treffer bis +9 %;Waffe: langsamer Zweihaender - Siegel und Richturteil wirken pro Schlag;Rotation: Siegel der Rechtschaffenheit/des Befehls, Richturteil, Siegel neu setzen;Tipp: Weihe nur mit genug Mana, Segen der Macht fuer dich"] = "Характеристики: сила (1 очко = 2 СА), крит, меткость до +9 %;Оружие: медленное двуручное - печати и Правосудие действуют за удар;Ротация: Печать праведности/повеления, Правосудие, обновить печать;Совет: Освящение только при достатке маны, Благословение могущества на себя"
T["Werte: Treffer bis +9 %, Beweglichkeit (1 AP, ca. 29 = 1 % Krit), AP, Krit;Waffe: Kampf = schnelle Nebenhand, langsame Haupthand (Finsterer Stoss); Dolche fuer Meucheln;Rotation: Combopunkte aufbauen, Zerhaecksler oben halten, dann Ausweiden;Tipp: mit zwei Waffen verfehlen normale Schlaege oefter - Treffer ist am wichtigsten"] = "Характеристики: меткость до +9 %, ловкость (1 СА, ок. 29 = 1 % крита), СА, крит;Оружие: Бой = быстрое в левой, медленное в правой (Коварный удар); кинжалы для Удара в спину;Ротация: копить приёмы серии, держать Мясорубку, затем Потрошение;Совет: с двумя оружиями белые удары чаще промахиваются - меткость важнее всего"
T["Werte: Treffer bis +9 %, Beweglichkeit (2 Distanz-AP, ca. 53 = 1 % Krit), AP, Intelligenz;Waffe: langsame Distanzwaffe (hoher Schaden pro Schuss), Nahkampfwaffe mit Werten;Rotation: Mal des Jaegers, Automatischer Schuss, Zielschuss/Mehrfachschuss dazwischen;Tipp: Begleiter fuettern und gluecklich halten, Eisfalle (Quadrat) als Kontrolle"] = "Характеристики: меткость до +9 %, ловкость (2 СА дальн. боя, ок. 53 = 1 % крита), СА, интеллект;Оружие: медленное оружие дальнего боя (большой урон за выстрел), оружие ближнего боя ради характеристик;Ротация: Метка охотника, Автоматическая стрельба, Прицельный/Залп между ними;Совет: корми питомца и держи его довольным, Замораживающая ловушка (квадрат) для контроля"
T["Werte: Treffer bis +9 %, Staerke (1 Punkt = 2 AP), Krit (ca. 20 Beweglichkeit = 1 %);Waffe: langsamer Zweihaender (Toedlicher Stoss, Heldenhafter Stoss wirken pro Schlag);Rotation: Wut aufbauen, Toedlicher Stoss / Blutdurst, Wirbelwind, ueberschuessige Wut in Heldenhaften Stoss;Tipp: Kampfrausch-Ruf vor dem Kampf, Hinrichten unter 20 % Leben"] = "Характеристики: меткость до +9 %, сила (1 очко = 2 СА), крит (ок. 20 ловкости = 1 %);Оружие: медленное двуручное (Смертельный удар, Удар героя действуют за удар);Ротация: копить ярость, Смертельный удар / Кровожадность, Вихрь, лишняя ярость в Удар героя;Совет: Боевой крик перед пуллом, Казнь ниже 20 % здоровья"
T["Werte: Verteidigung (440 = auf 60 kritsicher gegen Bosse), Ausdauer, Ruestung, Schildblock;Waffe: Einhandwaffe + Schild, schnelle Waffe = mehr Wut;Rotation: Schildschlag/Rachsucht, Ruestung zerreissen auf das Ziel, Heldenhafter Stoss bei viel Wut;Tipp: Treffer hilft, damit Spott und Faehigkeiten nicht verfehlen"] = "Характеристики: защита (440 = на 60 ур. иммунитет к критам боссов), выносливость, броня, блок;Оружие: одноручное + щит, быстрое оружие = больше ярости;Ротация: Мощный удар щитом/Реванш, Раскол брони на цель, Удар героя при избытке ярости;Совет: меткость помогает, чтобы Провокация и умения не промахивались"
T["Werte: Verteidigung, Ausdauer, Ruestung, dann Zauberschaden fuer mehr Bedrohung;Waffe: Einhandwaffe (gern mit Zauberschaden) + Schild;Rotation: Zorn der Gerechtigkeit an, Weihe fuer Gruppen, Heiliger Schild oben halten;Tipp: Mana ist knapp - Siegel der Weisheit oder Intelligenz mitnehmen"] = "Характеристики: защита, выносливость, броня, затем урон от заклинаний ради угрозы;Оружие: одноручное (лучше с уроном от заклинаний) + щит;Ротация: Праведное неистовство вкл., Освящение для групп, держать Щит небес;Совет: маны мало - бери Печать мудрости или немного интеллекта"
T["Werte: Zauberschaden, Zauber-Krit (Elementarfokus spart Mana), Intelligenz, Mana-Reg.;Waffe: Einhandwaffe + Schild/Nebenhand mit Zauberschaden;Rotation: Blitzschlag spammen, Kettenblitz bei Gruppen, Flammenschock;Tipp: Zaubertreffer bis +16 % im Raid, Manaquelle-Totem gegen leeres Mana"] = "Характеристики: урон от заклинаний, крит заклинаний (Сосредоточенность стихий экономит ману), интеллект, восст. маны;Оружие: одноручное + щит/левая рука с уроном от заклинаний;Ротация: спамить Молнию, Цепная молния по группам, Огненный шок;Совет: меткость заклинаний до +16 % в рейде, Тотем источника маны против нехватки маны"
T["Werte: Zauberschaden, Zauber-Krit, Intelligenz, Zaubertreffer bis +16 % im Raid;Waffe: Stab oder Einhandwaffe + Nebenhand mit Zauberschaden;Rotation: Mondfeuer + Insektenschwarm, dann Zorn oder Sternenfeuer;Tipp: Anregen fuer dich selbst, wenn das Mana knapp wird"] = "Характеристики: урон от заклинаний, крит заклинаний, интеллект, меткость заклинаний до +16 % в рейде;Оружие: посох или одноручное + левая рука с уроном от заклинаний;Ротация: Лунный огонь + Рой насекомых, затем Гнев или Звёздный огонь;Совет: Озарение на себя, когда маны мало"
T["Werte: Zauberschaden, Zaubertreffer bis +16 % (Raid), Ausdauer, Intelligenz;Waffe: Stab oder Dolch + Nebenhand mit Zauberschaden, Zauberstab fuer Restmana;Rotation: Verderbnis + Fluch, dann Schattenblitz; Aderlass statt Trinken;Tipp: Ausdauer lohnt sich doppelt (Aderlass, Leerwandler/Seelenverbindung)"] = "Характеристики: урон от заклинаний, меткость заклинаний до +16 % (рейд), выносливость, интеллект;Оружие: посох или кинжал + левая рука с уроном от заклинаний, жезл для остатков маны;Ротация: Порча + проклятие, затем Стрела Тьмы; Жизнеотвод вместо питья;Совет: выносливость окупается вдвойне (Жизнеотвод, Демон Бездны/Связка душ)"
T["Werte: Zauberschaden, Zaubertreffer bis +16 % (Raid), Willenskraft fuer Mana;Waffe: Stab oder Einhandwaffe + Nebenhand mit Zauberschaden;Rotation: Schattenwort: Schmerz, Gedankenschlag, Gedankenschinden;Tipp: Schattengestalt dauerhaft an, Vampirumarmung heilt die Gruppe"] = "Характеристики: урон от заклинаний, меткость заклинаний до +16 % (рейд), дух для маны;Оружие: посох или одноручное + левая рука с уроном от заклинаний;Ротация: Слово Тьмы: Боль, Взрыв разума, Пытка разума;Совет: постоянно в Облике Тьмы, Объятия вампира лечат группу"
T["Werte: Zauberschaden, dann Zaubertreffer bis +16 % (Raid-Bosse), Intelligenz, Zauber-Krit;Waffe: Stab mit Zauberschaden, dazu ein Zauberstab fuer Restmana;Rotation: Frostblitz bzw. Feuerball spammen, Hervorrufung bei leerem Mana;Leveln: Intelligenz und Willenskraft = weniger Pausen, in Gruppen Schaf (Mond) setzen"] = "Характеристики: урон от заклинаний, затем меткость заклинаний до +16 % (рейдовые боссы), интеллект, крит заклинаний;Оружие: посох с уроном от заклинаний плюс жезл для остатков маны;Ротация: спамить Ледяную стрелу или Огненный шар, Прилив сил без маны;Прокачка: интеллект и дух = меньше пауз, в группах ставь овцу (луна)"
