T["Zeigt BESSER / SCHLECHTER / NICHT TRAGBAR mit Auswirkung (DPS, Leben, Ruestung) und Werte-Tabelle. Blizzards Vergleich erscheint dann nur mit Shift. Ist nesUI mit eigenem Vergleich geladen, zeigt Oasis nichts (sonst doppelt) - dort mit /nes vergleich abschalten."] = "Показывает ЛУЧШЕ / ХУЖЕ / НЕЛЬЗЯ НАДЕТЬ с эффектом (УВС, здоровье, броня) и таблицей характеристик. Сравнение Blizzard тогда только с Shift. Если загружен nesUI со своим сравнением, Oasis ничего не показывает (иначе дубль) - выключить там: /nes vergleich."
T["Zeigt Besser / Schlechter / Nicht tragbar mit Auswirkung (DPS, Leben, Ruestung) und Werte-Tabelle. Blizzards Vergleich erscheint dann nur mit Shift. Ist nesUI mit eigenem Vergleich geladen, zeigt Oasis nichts (sonst doppelt) - dort mit /nes vergleich abschalten."] = "Показывает лучше / хуже / нельзя надеть с эффектом (УВС, здоровье, броня) и таблицей характеристик. Сравнение Blizzard тогда только с Shift. Если загружен nesUI со своим сравнением, Oasis ничего не показывает (иначе дубль) - выключить там: /nes vergleich."
T["Zeigt Beute aus Dungeons deines Levelbereichs, die besser ist als dein angelegtes Teil."] = "Показывает добычу из подземелий твоего уровня, которая лучше надетого предмета."
T["Zeigt ab Oasis-Rang 30 ein Juwel und ab Rang 70 einen schimmernden Namen im Oasis-Gildenchat"] = "С ранга Oasis 30 показывает самоцвет, с ранга 70 - мерцающее имя в чате гильдии Oasis"
T["Zeigt die Levelspanne der Gebiete"] = "Показывает диапазон уровней зон"
T["Zeigt einen Hinweis, sobald jemand aus der Gilde einen neuen Termin anlegt"] = "Показывает уведомление, как только кто-то из гильдии создаёт новое событие"
T["Zeigt im Brachland ab und zu typische Sprueche im allgemeinen Chat - Chuck Norris, Mankriks Frau ... Nur bei dir, nichts wird gesendet."] = "В Степях иногда показывает типичные фразы в общем чате - Чак Норрис, жена Манкрика ... Только у тебя, ничего не отправляется."
T["Zeigt im Item-Tooltip, wer das Item fuer einen anstehenden Termin reserviert hat"] = "Показывает в подсказке предмета, кто зарезервировал его на ближайшее событие"
