T["1 Upgrade"] = "1 улучшение"
T["1.  Kampflog mitschreiben lassen (Einstellungen > Bereiche > Kampf-Rangliste, steht auf an).\n2.  Nach dem Spielen im Oasis-Ordner ImportCrits.bat doppelklicken.\n3.  Im Spiel /reload - dein hoechster Crit steht hier und wird mit der Gilde geteilt."] = "1.  Оставь журнал боя включённым (Настройки > Разделы > Рейтинг боёв, включено по умолчанию).\n2.  После игры дважды щёлкни ImportCrits.bat в папке Oasis.\n3.  В игре /reload - твой лучший крит появится здесь и будет виден гильдии."
T["1. Ueberschrift"] = "1. Заголовок"
