T["Aktiv: Meme-Sounds, Musik und Gilden-Emojis sind enthalten."] = "Активно: мем-звуки, музыка и эмодзи гильдии включены."
T["Aktive Mitglieder unterhalb der Offiziersraenge erscheinen nach so vielen Tagen im selben Rang in der Liste 'Befoerderung'. 0 = aus."] = "Активные участники ниже офицерских рангов попадают в список «Повышение» после стольких дней в одном ранге. 0 = выкл."
T["Aktuelles Gebiet zuerst"] = "Сначала текущая зона"
T["Alle Bereiche, nach Themen gruppiert: Gilde, Zusammen spielen, Raid, Handel, Spass. Ein Klick auf eine Ueberschrift klappt die Gruppe zu."] = "Все разделы по темам: гильдия, совместная игра, рейд, торговля, развлечения. Клик по заголовку сворачивает группу."
T["Alle Gebiete aufklappen"] = "Развернуть все зоны"
T["Alle Gebiete zuklappen"] = "Свернуть все зоны"
T["Alle Mitglieder mit Rang, Stufe und Oasis-Version. Rechtsklick auf eine Zeile: Rang aendern."] = "Все участники с рангом, уровнем и версией Oasis. ПКМ по строке: сменить ранг."
T["Alle Schriften unter der SIL Open Font License 1.1"] = "Все шрифты под лицензией SIL Open Font License 1.1"
T["Alle: Brennendes Adrenalin: SOFORT aus dem Raid laufen (du stirbst gleich).\nAlle: Volle Ressourcen am Anfang - alles raushauen.\nTank: Tank-Reihenfolge festlegen (Adrenalin auf dem Tank).\nDD: Nicht vor oder hinter den Drachen."] = "All: Жгучий адреналин: СРАЗУ выбегай из рейда (ты сейчас умрёшь).\nAll: Полные ресурсы в начале - используй всё.\nTank: Назначить порядок танков (Адреналин на танке).\nDD: Не стоять перед драконом и за ним."
T["Alle: Die 8 Feuerwichtel nicht in der Naehe des Raids sterben lassen (Explosion).\nTank: Jeder Wichtel-Tank zieht seinen Wichtel weg, Hexer verbannen.\nHeiler: Bannen, Wichtel-Tanks im Blick.\nDD: Garr zuerst, Wichtel nur gezielt."] = "All: Не давайте 8 Firesworn умирать рядом с рейдом (взрыв).\nTank: Каждый танк аддов уводит своего Firesworn, чернокнижники изгоняют.\nHealer: Рассеивать, следить за танками аддов.\nDD: Сначала Гарр, адды только по команде."
T["Alle: Die beiden Kernhunde weg vom Boss tanken, nicht toeten.\nTank: Golemagg-Tank wechseln, wenn Magmasplitter zu hoch stapeln.\nDD: Nur auf Golemagg."] = "All: Двух Core Rager танковать в стороне от босса, не убивать.\nTank: Менять танка Големагга, когда Magma Splash стакается слишком высоко.\nDD: Только Големагг."
T["Alle: Erst die 4 Priester, sie heilen sich gegenseitig.\nTank: Herold und Priester getrennt.\nDD: Unterbrechen! Dunkle Besserung der Priester stoppen."] = "All: Сначала 4 жреца, они лечат друг друга.\nTank: Держать Сульфурона и жрецов раздельно.\nDD: Прерывать! Сбивать Dark Mending жрецов."
T["Alle: Feuerschutz! Wrath of Ragnaros wirft den Nahkampf weg - danach wieder ran.\nAlle: Phase der Soehne (nach 3 Min oder bei Untertauchen): alle Soehne der Flamme toeten.\nTank: Zweiter Tank bereit, wenn der erste weggeworfen wird.\nHeiler: Verteilt, Fernkampf nicht zu nah (Lavaplatscher).\nDD: Nahkampf: Mana unter Kontrolle, Fernkampf auf Abstand."] = "All: Защита от огня! Гнев Рагнароса отбрасывает ближний бой - потом снова к боссу.\nAll: Фаза сыновей (через 3 мин или при погружении): убить всех Сыновей пламени.\nTank: Второй танк наготове, когда первого отбросит.\nHealer: Рассредоточиться, дальний бой не слишком близко (Lava Burst).\nDD: Ближний бой: следить за маной, дальний бой - на дистанции."
T["Alle: Flammenpuffer stapelt - Fernkampf hinter Saeulen zum Abbauen.\nTank: Zwei Tanks hinter Saeulen, Flugelschlag wirft zurueck.\nDD: Onyxiaschuppenumhang Pflicht."] = "All: Flame Buffet стакается - дальний бой за колонны, чтобы спал.\nTank: Два танка за колоннами, Wing Buffet отбрасывает.\nDD: Плащ из чешуи Ониксии обязателен."
T["Alle: Fluch des Gehennas (weniger Heilung) sofort entfernen.\nAlle: Aus dem Feuerregen raus.\nTank: Die zwei Flammenwichtel getrennt tanken.\nDD: Wichtel zuerst, dann Gehennas."] = "All: Проклятие Гееннаса (меньше лечения) снимать сразу.\nAll: Выйти из Огненного ливня.\nTank: Двух Flamewaker танковать раздельно.\nDD: Сначала Flamewaker, потом Гееннас."
T["Alle: Fluch des Lucifron und Drohende Verdammnis sofort entfernen (Magier/Druiden, Priester/Paladine).\nTank: Die beiden Wachen getrennt tanken - Gedankenkontrolle!\nHeiler: Verteilt stehen, gedankenkontrollierte Spieler bannen.\nDD: Erst die Wachen, dann Lucifron."] = "All: Проклятие Люцифрона и Impending Doom снимать сразу (маги/друиды, жрецы/паладины).\nTank: Двух стражей танковать раздельно - контроль над разумом!\nHealer: Рассредоточиться, рассеивать подконтрольных игроков.\nDD: Сначала стражи, потом Люцифрон."
T["Alle: Lebende Bombe: SOFORT raus aus dem Raid laufen!\nAlle: Inferno - weg vom Boss, Mana-Ausloeschung bannen.\nTank: Mitte halten, bei Inferno kurz raus.\nDD: Nahkampf bei Inferno zurueck."] = "All: Живая бомба: СРАЗУ выбегай из рейда!\nAll: Инферно - от босса, рассеивать Ignite Mana.\nTank: Держать центр, на Инферно ненадолго выйти.\nDD: Ближний бой на Инферно отходит."
T["Alle: Magiereflexion/Schadensschild der Wachen beachten - dann Schaden stoppen.\nTank: Jeder Tank eine Wache, Magier schafen die Elitewachen.\nDD: Heiler-Wachen (Flamewaker Healer) zuerst."] = "All: Следить за отражением магии/щитом урона стражей - тогда стоп урон.\nTank: По стражу на танка, маги превращают элитных стражей в овец.\nDD: Сначала стражи-лекари (Flamewaker Healer)."
T["Alle: Nie vor oder hinter Onyxia stehen (Atem und Schwanzfeger).\nAlle: Phase 2 (65%): Feuerbaellen ausweichen, nicht in die Hoehlen-Eingaenge.\nAlle: Phase 3 (40%): Furcht - Furchtschutz/Erdungstotem bereit, Lava-Risse meiden.\nTank: Onyxia seitlich an der Wand, Kopf weg vom Raid.\nTank: Phase 2: Welpen einsammeln. Phase 3: Aggro sofort zurueck.\nHeiler: Tank hat Vorrang, in Phase 2 verteilt stehen.\nDD: 3 Angriffe des Tanks abwarten. Phase 2: Welpen zuerst."] = "All: Никогда не стоять перед Ониксией и за ней (дыхание и удар хвостом).\nAll: Фаза 2 (65%): уворачиваться от огненных шаров, не заходить во входы пещер.\nAll: Фаза 3 (40%): страх - Защита от страха/Тотем трепета наготове, избегать трещин с лавой.\nTank: Ониксия боком у стены, головой от рейда.\nTank: Фаза 2: собрать дракончиков. Фаза 3: сразу вернуть агро.\nHealer: Танк в приоритете, в фазе 2 рассредоточиться.\nDD: Подождать 3 атаки танка. Фаза 2: сначала дракончики."
T["Alle: Panik - Furchtschutz/Erdungstotem, Jaeger: Einlullender Schuss bei Raserei.\nAlle: Aus dem Lavafeuer am Boden raus.\nTank: Magmadar mit dem Ruecken zum Raid.\nDD: Fernkampf hinten verteilt."] = "All: Паника - Защита от страха/Тотем трепета, охотники: Усмиряющий выстрел на Бешенство.\nAll: Выйти из огня на полу.\nTank: Магмадар спиной к рейду.\nDD: Дальний бой рассредоточен сзади."
T["Alle: Phase 1: Drachkin aus beiden Seiten, Klassenrufe beachten.\nAlle: Phase 3 (20%): Skelette wieder auferstanden - erneut toeten.\nTank: Nefarian an der Wand, Furcht - Furchtschutz.\nHeiler: Klassenruf fuer Priester: Heilung schadet - aufpassen.\nDD: Jaeger/Krieger: Klassenrufe beachten (Waffen weg, Haltung)."] = "All: Фаза 1: драконоры с обеих сторон, следить за классовыми призывами.\nAll: Фаза 3 (20%): скелеты встают снова - убить ещё раз.\nTank: Нефариан у стены, страх - Защита от страха.\nHealer: Призыв для жрецов: лечение наносит урон - осторожно.\nDD: Охотники/воины: следить за призывами (оружие пропадает, стойка)."
T["Alle: Phase 1: Eier zerstoeren (Gedankenkontrolle der Kugel), Adds abfangen.\nAlle: Nach allen Eiern: Boss im Raum - Feuerball-Nova.\nTank: Adds an den Treppen sammeln.\nDD: Magier und Drachkin zuerst."] = "All: Фаза 1: уничтожать яйца (контроль над разумом через сферу), перехватывать аддов.\nAll: После всех яиц: босс в комнате - Fire Nova.\nTank: Собирать аддов у лестниц.\nDD: Сначала маги и драконоры."
T["Alle: Raserei - Jaeger: Einlullender Schuss.\nTank: Zwei Tanks, Flugelschlag beachten.\nDD: Onyxiaschuppenumhang Pflicht."] = "All: Бешенство - охотники: Усмиряющий выстрел.\nTank: Два танка, следить за Wing Buffet.\nDD: Плащ из чешуи Ониксии обязателен."
T["Alle: Schatten der Schattenschwinge heilt den Boss - Tank mit Debuff tauscht.\nTank: Zwei Tanks wechseln bei Schatten.\nDD: Onyxiaschuppenumhang Pflicht."] = "All: Shadow of Ebonroc лечит босса - танк с дебаффом меняется.\nTank: Два танка меняются на Shadow.\nDD: Плащ из чешуи Ониксии обязателен."
T["Alle: Stoss zurueck - an die Wand stellen.\nTank: Zwei Tanks, Aggro wird durch Niederschlagen geteilt.\nDD: Mortalschlag auf Tank: Heiler vorbereiten."] = "All: Отбрасывание - встать к стене.\nTank: Два танка, агро делится из-за Knock Away.\nDD: Смертельный удар по танку: лекарям быть готовыми."
T["Alle: Teleportiert sich - wer Aggro hat, nicht wegrennen.\nAlle: Fluch des Shazzrah entfernen, Arkane Explosion: Nahkampf auf Abstand.\nTank: Nach jedem Blinzeln sofort wieder ran.\nHeiler: Bannen (Deaktivieren-Magie)."] = "All: Он телепортируется - у кого агро, не убегать.\nAll: Снимать Проклятие Шаззраха, Чародейский взрыв: ближний бой на дистанции.\nTank: После каждого скачка сразу обратно к нему.\nHealer: Рассеивать (Deaden Magic)."
T["Alle: Zwei der fuenf Atem-Arten je Woche - Atem verlaesst man hinter der Ecke.\nAlle: Hourglass Sand fuer Bronze-Affliktion.\nTank: Am Tor tanken, Raid hinter der Ecke.\nDD: Bei Raserei Einlullender Schuss."] = "All: Два из пяти видов дыхания в неделю - от дыхания прятаться за углом.\nAll: Hourglass Sand от бронзового недуга.\nTank: Танковать у ворот, рейд за углом.\nDD: На Бешенство - Усмиряющий выстрел."
T["Alt halten: alle Werte und Bewertung. Shift: Blizzard-Vergleich."] = "Удерживай Alt: все характеристики и оценка. Shift: сравнение Blizzard."
T["Alt loslassen: kompakter Vergleich. Shift: Blizzard-Vergleich."] = "Отпусти Alt: компактный вид. Shift: сравнение Blizzard."
T["Altes Oasis"] = "Старый Oasis"
T["An: mit der Maus an eine eigene Stelle ziehen. Aus: haengt am Talentfenster."] = "Вкл: перетащи мышью куда угодно. Выкл: прикреплено к окну талантов."
T["Anfuehrer der Dunkelspeere"] = "Вождь Чёрного Копья"
T["Angefangener Text bleibt beim Wechsel des Gespraechs stehen"] = "Неотправленный текст сохраняется при смене беседы"
T["Animationen aus"] = "Отключить анимации"
T["Ansprechpartner"] = "Контакт"
T["Anwesenheit und Ausruestung der Gilde im Blick."] = "Следи за посещаемостью и экипировкой гильдии."
T["Auf dem Flug nichts erkennen oder melden"] = "В полёте ничего не определять и не сообщать"
T["Auf dem Flugmeister-Flug kannst du ohnehin nicht anhalten"] = "В полёте всё равно нельзя остановиться"
T["Aus FojjiCore (%d)"] = "Из FojjiCore (%d)"
T["Aus Guides zur Forever-Beta - kann sich noch aendern."] = "Из гайдов по бете Forever - может измениться."
T["Aus dem Soundpaket (ruhig)"] = "Из набора звуков (спокойный)"
T["Aus: das Fenster verschwindet. Zurueck mit /oa builds."] = "Выкл: окно исчезает. Вернуть: /oa builds."
T["Ausfuehrliche Karten"] = "Подробные карточки"
T["Ausklappen"] = "Развернуть"
T["Ausloggen: Blizzards Dialogliste war von Oasis beruehrt (ab 0.5.478 behoben - bitte Oasis aktualisieren)."] = "Выход: список диалогов Blizzard был затронут Oasis (исправлено в 0.5.478 - обнови Oasis)."
