T["Das war nur Glueck! Nochmal!"] = "Просто повезло! Ещё раз!"
T["Das war's schon. Den Rundgang findest du jederzeit wieder unter Einstellungen > Status oder mit /oa rundgang."] = "Вот и всё. Экскурсию всегда можно найти в Настройки > Статус или через /oa rundgang."
T["Daten"] = "Данные"
T["Deckend"] = "Непрозрачно"
T["Dein Charakter"] = "Твой персонаж"
T["Deine Stats: Oasis-Rang, Abzeichen und alle Zaehler"] = "Твоя статистика: ранг Oasis, значки и все счётчики"
T["Den Download findest du im Discord der Gilde."] = "Ссылка на загрузку - в Discord гильдии."
T["Der Client erlaubt Oasis nicht, das Kampflog einzuschalten - bitte selbst /combatlog eingeben."] = "Клиент не даёт Oasis включить журнал боя - введи /combatlog сам."
T["Der Inhalt des gewaehlten Bereichs. Die Uebersicht zeigt, wer online ist, was ansteht und was es Neues gibt."] = "Содержимое выбранного раздела. Обзор показывает, кто в сети, что предстоит и что нового."
T["Der Minimap-Knopf oder /oa oeffnet Oasis. Mit dem Strich oben rechts wird das Fenster zu einer schmalen Leiste."] = "Кнопка у миникарты или /oa открывает Oasis. Чёрточка справа вверху превращает окно в узкую панель."
T["Der Offizierskanal (/o) mit Verlauf - nur fuer Raenge mit Offizierschat-Recht."] = "Офицерский канал (/o) с историей - только для рангов с правом офицерского чата."
T["Der gelbe Strich links in der Liste zeigt das an."] = "На это указывает жёлтая полоска слева в списке."
T["Details schliessen"] = "Закрыть подробности"
T["Deutlicher Standard-Ton bei Online-Meldungen"] = "Чёткий стандартный звук для уведомлений о входе в сеть"
T["Die Charakterstatistik ist in diesem Client nicht verfuegbar."] = "Статистика персонажа недоступна в этом клиенте."
T["Die Gildenleitung hat Soundeffekte fuer dich gesperrt."] = "Руководство гильдии отключило тебе звуковые эффекты."
T["Die Leiste ist ab dem Einloggen da und bleibt - das X am Fenster schliesst nur das Fenster."] = "Панель есть с момента входа и остаётся - X на окне закрывает только окно."
T["Die Prozentzahl vergleicht die Item-Wertung fuer deine Rolle, nicht deinen gesamten Schaden. Auswirkungen sind Schaetzwerte."] = "Процент сравнивает оценку предмета для твоей роли, а не весь твой урон. Эффекты - приблизительные."
T["Die Statistik liefert derzeit keinen lesbaren Wert."] = "Статистика сейчас не даёт читаемого значения."
T["Die Zentrale eurer Gilde. In 30 Sekunden kennst du dich aus - hier ist das Wichtigste."] = "Центр вашей гильдии. За 30 секунд ты освоишься - вот самое важное."
T["Die geschuetzte Funktion wurde blockiert. Der genaue Ausloeser ist noch unbekannt."] = "Защищённая функция была заблокирована. Точная причина пока неизвестна."
T["Die passende Charakterstatistik wurde noch nicht gefunden."] = "Подходящая статистика персонажа пока не найдена."
T["Die vollstaendigen Lizenztexte liegen im Oasis-Ordner: CREDITS.txt, LICENSE und LICENSE-MIT.txt."] = "Полные тексты лицензий лежат в папке Oasis: CREDITS.txt, LICENSE и LICENSE-MIT.txt."
T["Diese Gildenraenge (0 = Gildenmeister) duerfen im Beuterat abstimmen."] = "Эти ранги гильдии (0 = глава гильдии) могут голосовать в совете по добыче."
T["Dieser Charakter liegt auf einem anderen WoW-Account und hat dich als Main eingetragen. Nur wenn du bestaetigst, zaehlt er in der Gilde als dein Twink."] = "Этот персонаж на другом аккаунте WoW и указал тебя основным. Твоим твинком в гильдии он станет, только если ты подтвердишь."
T["Dieser Client liefert keine Addon-Messwerte (C_AddOnProfiler fehlt)."] = "Этот клиент не даёт данных об аддонах (нет C_AddOnProfiler)."
