T["Wieder am Talentfenster andocken"] = "Снова прикрепить к окну талантов"
T["WoW sagt Addons in der Gruppe nicht, wer getroffen hat. Oasis zaehlt einen kritischen Treffer nur, wenn er direkt auf deinen eigenen Angriff folgt und nach dem Kampf zur Schadensanzeige passt. In der Rangliste als geschaetzt markiert."] = "В группе WoW не сообщает аддонам, кто нанёс удар. Oasis считает крит, только если он идёт сразу за твоей атакой и после боя совпадает со счётчиком урона. В рейтинге помечен как оценочный."
T["WoW-Klassiker"] = "Классика WoW"
T["Wochenaufgaben %d/%d"] = "Недельные задания %d/%d"
T["World of Warcraft und zugehoerige Namen, Wappen und Grafiken sind Marken von Blizzard Entertainment. Oasis ist ein Fan-Projekt und steht in keiner Verbindung zu Blizzard."] = "World of Warcraft и связанные названия, гербы и графика - товарные знаки Blizzard Entertainment. Oasis - фанатский проект и не связан с Blizzard."
T["Wuerfeln: Reihenfolge Bedarf > Zweitspec > Transmog, dann Wurf. Punkte: Prioritaet aus den Beutepunkten entscheidet. Beuterat: Offiziere stimmen ab, der Plundermeister vergibt."] = "Броски: порядок нужда > доп. специализация > трансмог, затем бросок. Очки: решает приоритет по очкам добычи. Совет по добыче: офицеры голосуют, ответственный за добычу выдаёт."
T["Zahnrad = Einstellungen (Aussehen, Toene, Hinweise). Daneben Sprache und - fuer die Gildenleitung - die Krone."] = "Шестерёнка = настройки (вид, звуки, уведомления). Рядом язык и - для руководства гильдии - корона."
T["Zeigt bei gruenen, blauen und epischen Teilen, welche Materialien beim Entzaubern herauskommen koennen"] = "Показывает, какие материалы можно получить при распылении зелёных, синих и эпических предметов"
T["Zeigt in der Suche an, dass ihr per Sprache redet (Discord o.ae.). Beitreten regelt weiter Blizzard bzw. dein Gruppenleiter."] = "Показывает в поиске, что вы общаетесь голосом (Discord и т.п.). Вступлением по-прежнему управляет Blizzard / лидер группы."
T["Zeigt nur Mains. Twinks sind Charaktere, die einem anderen Main zugeordnet sind."] = "Показывает только основных. Твинки - персонажи, привязанные к другому основному."
T["Zeigt nur die Kopfzeile mit der Anzahl der Builds."] = "Показывает только заголовок с числом билдов."
T["Zeigt sofort, wer aus der Gilde dieselben Quests hat und gerade online ist - ein Klick laedt ihn ein."] = "Сразу показывает, у кого в гильдии те же задания и кто сейчас в сети - один клик приглашает."
T["Zielt jemand einen Boss an, zu dem es eine Taktik gibt, erscheint ein kurzer Hinweis (ausserhalb des Kampfes)."] = "Если кто-то берёт в цель босса, для которого есть тактика, появляется короткая подсказка (вне боя)."
